/**
 * Minimal subset of the Codex App Server (v2) protocol used by this extension.
 *
 * Hand-copied from the bindings generated by
 *   codex app-server generate-ts --out <dir>      (codex-cli 0.154.0)
 * Only fields we read or send are declared; everything else is preserved as
 * `unknown`. Unknown item types / notifications are tolerated, never fatal.
 *
 * Wire format: JSON-RPC 2.0 messages, one per line (JSONL) over stdio, with
 * the `"jsonrpc": "2.0"` member omitted.
 */

export type RequestId = string | number;

export interface RpcRequest {
  id: RequestId;
  method: string;
  params?: unknown;
}
export interface RpcNotification {
  method: string;
  params?: unknown;
}
export interface RpcResponse {
  id: RequestId;
  result?: unknown;
  error?: { code: number; message: string; data?: unknown };
}
export type RpcMessage = RpcRequest | RpcNotification | RpcResponse;

// ------------------------------------------------------------------ policy

export type AskForApproval = 'untrusted' | 'on-request' | 'never';
export type SandboxMode = 'read-only' | 'workspace-write' | 'danger-full-access';

export type SandboxPolicy =
  | { type: 'readOnly'; networkAccess: boolean }
  | {
      type: 'workspaceWrite';
      writableRoots: string[];
      networkAccess: boolean;
      excludeTmpdirEnvVar: boolean;
      excludeSlashTmp: boolean;
    };

// ------------------------------------------------------------------ threads

export interface ThreadStartParams {
  cwd: string;
  approvalPolicy: AskForApproval;
  sandbox: SandboxMode;
  model?: string | null;
  serviceName?: string | null;
  developerInstructions?: string | null;
  /** Ephemeral threads are not persisted to the user's Codex history. */
  ephemeral?: boolean | null;
}
export interface ThreadStartResponse {
  thread: { id: string };
  model: string;
  cwd: string;
  approvalPolicy: unknown;
  sandbox: unknown;
}

export interface TextInput {
  type: 'text';
  text: string;
  text_elements: unknown[];
}

export interface TurnStartParams {
  threadId: string;
  input: TextInput[];
  cwd?: string;
  approvalPolicy?: AskForApproval;
  sandboxPolicy?: SandboxPolicy;
}
export type TurnStatus = 'completed' | 'interrupted' | 'failed' | 'inProgress';
export interface Turn {
  id: string;
  status: TurnStatus;
  error: { message: string } | null;
  items?: ThreadItem[];
}
export interface TurnSteerParams {
  threadId: string;
  input: TextInput[];
  expectedTurnId: string;
}
export interface TurnInterruptParams {
  threadId: string;
  turnId: string;
}

// -------------------------------------------------------------------- items

export type CommandAction =
  | { type: 'read'; command: string; name: string; path: string }
  | { type: 'listFiles'; command: string; path: string | null }
  | { type: 'search'; command: string; query: string | null; path: string | null }
  | { type: 'unknown'; command: string };

export type ItemStatus = 'inProgress' | 'completed' | 'failed' | 'declined';

export interface FileUpdateChange {
  path: string;
  kind: { type: 'add' } | { type: 'delete' } | { type: 'update'; move_path: string | null };
  diff: string;
}

export type ThreadItem =
  | {
      type: 'commandExecution';
      id: string;
      command: string;
      cwd: string;
      status: ItemStatus;
      commandActions: CommandAction[];
      aggregatedOutput: string | null;
      exitCode: number | null;
      durationMs: number | null;
    }
  | { type: 'fileChange'; id: string; changes: FileUpdateChange[]; status: ItemStatus }
  | {
      type: 'mcpToolCall';
      id: string;
      server: string;
      tool: string;
      status: string;
      error: { message?: string } | null;
    }
  | { type: 'agentMessage'; id: string; text: string }
  | { type: 'reasoning'; id: string; summary?: string[] }
  | { type: 'plan'; id: string; text: string }
  | { type: 'userMessage'; id: string }
  | { type: 'webSearch'; id: string; query?: string }
  | { type: string; id: string; [k: string]: unknown };

export interface ItemNotification {
  item: ThreadItem;
  threadId: string;
  turnId: string;
}
export interface TurnNotification {
  threadId: string;
  turn: Turn;
}
export interface OutputDeltaNotification {
  threadId: string;
  turnId: string;
  itemId: string;
  delta: string;
}
export interface ErrorNotification {
  error: { message: string };
  willRetry: boolean;
  threadId: string;
  turnId: string;
}

// ---------------------------------------------------------------- approvals

export interface CommandApprovalParams {
  threadId: string;
  turnId: string;
  itemId: string;
  approvalId?: string | null;
  reason?: string | null;
  command?: string | null;
  cwd?: string | null;
  commandActions?: CommandAction[] | null;
}
export interface FileChangeApprovalParams {
  threadId: string;
  turnId: string;
  itemId: string;
  reason?: string | null;
  grantRoot?: string | null;
}
/**
 * We only ever answer with single-use decisions. `acceptForSession` and
 * policy amendments are deliberately never sent: each approval covers exactly
 * one operation.
 */
export type ApprovalDecision = 'accept' | 'decline' | 'cancel';

export const SERVER_REQUEST = {
  commandApproval: 'item/commandExecution/requestApproval',
  fileChangeApproval: 'item/fileChange/requestApproval',
  permissionsApproval: 'item/permissions/requestApproval',
  userInput: 'item/tool/requestUserInput',
  elicitation: 'mcpServer/elicitation/request',
  dynamicToolCall: 'item/tool/call',
  authRefresh: 'account/chatgptAuthTokens/refresh',
  attestation: 'attestation/generate',
  // Legacy (v1) approval methods, answered defensively.
  legacyExecApproval: 'execCommandApproval',
  legacyPatchApproval: 'applyPatchApproval',
} as const;

export function textInput(text: string): TextInput {
  return { type: 'text', text, text_elements: [] };
}
